(() => {
  const itens =
    $('AGRUPAR CONTEÚDO EXISTENTE').first().json.conteudos_existentes || [];

  const principal = itens.find(item =>
    String(item.content_type || '').toLowerCase() !== 'story'
  );

  const stories = itens
    .filter(item =>
      String(item.content_type || '').toLowerCase() === 'story'
    )
    .sort((a, b) =>
      Number(a.sequence_order || 0) - Number(b.sequence_order || 0)
    );

  if (!principal && stories.length === 0) {
    return '⚠️ Não encontrei conteúdo vinculado a este planejamento.';
  }

  let roteiro = '';

  if (principal && principal.script) {
    try {
      const cenas = JSON.parse(principal.script);

      if (Array.isArray(cenas)) {
        roteiro = cenas
          .map((cena, index) =>
            `${cena.ordem || index + 1}. ${cena.texto || ''}`
          )
          .join('\n');
      } else {
        roteiro = principal.script;
      }
    } catch (e) {
      roteiro = principal.script;
    }
  }

  const storiesTexto = stories
    .map((story, index) => {

      let interacao = '';

      if (story.cta) {
        try {
          const cta = JSON.parse(story.cta);

          if (cta && cta.tipo && cta.tipo !== 'nenhuma') {
            interacao = `\n🎯 Interação: ${cta.tipo}`;

            if (cta.opcoes && cta.opcoes.length) {
              interacao += ` — ${cta.opcoes.join(' / ')}`;
            }
          }
        } catch (e) {
          interacao = `\n🎯 Interação: ${story.cta}`;
        }
      }

      return `*Story ${story.sequence_order || index + 1}*

${story.script || ''}

🎥 *Visual*
${story.visual_brief || 'Sem orientação visual.'}${interacao}`;
    })
    .join('\n\n');

  return `📌 *CONTEÚDO EXISTENTE*

