const pedido = ($json.pedido_agendamento || '')
  .trim()
  .toUpperCase();

const timeZone = 'America/Sao_Paulo';

// Descobre a data de hoje em São Paulo
const partes = new Intl.DateTimeFormat('en-CA', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(new Date());

const anoHoje = Number(partes.find(p => p.type === 'year').value);
const mesHoje = Number(partes.find(p => p.type === 'month').value);
const diaHoje = Number(partes.find(p => p.type === 'day').value);

function formatarDataUTC(data) {
  const ano = data.getUTCFullYear();
  const mes = String(data.getUTCMonth() + 1).padStart(2, '0');
  const dia = String(data.getUTCDate()).padStart(2, '0');

  return `${ano}-${mes}-${dia}`;
}

let data;
let horario;

// HOJE 19:00
if (pedido.startsWith('HOJE ')) {
  const hoje = new Date(Date.UTC(
    anoHoje,
    mesHoje - 1,
    diaHoje
  ));

  data = formatarDataUTC(hoje);
  horario = pedido.replace(/^HOJE\s+/, '').trim();
}

// AMANHÃ 19:00
else if (
  pedido.startsWith('AMANHÃ ') ||
  pedido.startsWith('AMANHA ')
) {
  const amanha = new Date(Date.UTC(
    anoHoje,
    mesHoje - 1,
    diaHoje + 1
  ));

  data = formatarDataUTC(amanha);

  horario = pedido
    .replace(/^AMANHÃ\s+/, '')
    .replace(/^AMANHA\s+/, '')
    .trim();
}

// 25/09/2026 19:00
else {
  const match = pedido.match(
    /^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})$/
  );

  if (!match) {
    return {
      ...$json,
      agendamento_valido: false,
      erro_agendamento: 'Formato de data inválido.'
    };
  }

  const [, dia, mes, ano, hora, minuto] = match;

  const testeData = new Date(Date.UTC(
    Number(ano),
    Number(mes) - 1,
    Number(dia)
  ));

  const dataValida =
    testeData.getUTCFullYear() === Number(ano) &&
    testeData.getUTCMonth() + 1 === Number(mes) &&
    testeData.getUTCDate() === Number(dia);

  if (!dataValida) {
    return {
      ...$json,
      agendamento_valido: false,
      erro_agendamento: 'A data informada não existe.'
    };
  }

  data = `${ano}-${mes}-${dia}`;
  horario = `${hora}:${minuto}`;
}

// Valida horário
if (!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(horario)) {
  return {
    ...$json,
    agendamento_valido: false,
    erro_agendamento: 'Horário inválido.'
  };
}

return {
  ...$json,
  agendamento_valido: true,
  scheduled_for: `${data}T${horario}:00-03:00`
};

